    TestValidator.predicate(
      "order item has unit price",
      orderItem.unitPrice >= 0,
    );
    // 9. Validate seller reference
    const changedBySeller = detailResponse.changedBySeller;
    typia.assert(changedBySeller);
    TestValidator.equals(
