    string & tags.Format<"uuid">
  >();
  const inventoryRecordId2: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const inventoryRecordId3: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
