  );
  // Change filter and verify it returns page=1 by default
  const filteredResponse2 =
    await api.functional.ecommerceMall.admin.snapshot_audits.index(
      adminConnection,
      {
        body: { recordType: "product_variant", page: 2, limit: 50 },
      },
