  const emptySearchResult = await api.functional.ecommerceMall.categories.index(
    connection,
    {
      body: {
        search: "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx",
        limit: 20,
      },
    },
