/**
 * E2E test: Admin access to seller's product variant snapshots.
 *
 * Tests multi-role admin oversight scenario where admin can view
 * variant snapshots from another seller's products for platform
 * monitoring and dispute resolution.
 *
 * Business Rules:
 * - Section 409: Admins can view snapshots of any product
 * - Section 230: Snapshots are immutable audit records
 * - Section 1248: Snapshots capture before-after values
 * - Section 1095: Snapshot viewer permissions allow admin access
 */
export async function test_api_product_variant_snapshot_admin_access(
  connection: api.IConnection,
): Promise<void> {
  // =====================================================================
  // SETUP: Seller registration and authentication
  // =====================================================================
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuthorized = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(sellerAuthorized);
  // =====================================================================
  // SETUP: Admin registration for cross-seller oversight
  // =====================================================================
  const adminConnection: api.IConnection = { host: connection.host };
  const adminAuthorized = await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  typia.assert(adminAuthorized);
  // =====================================================================
  // SETUP: Create a variant for the product (seller's product)
  // =====================================================================
  // Use seed data productId for test environment
  const seedProductId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  // Create initial variant
  const initialVariantBody = {
    sku_code: RandomGenerator.alphaNumeric(12),
    option_values: {
      size: "Large",
      color: "Red",
    },
    stock_quantity: 100,
    price_override: null,
  } satisfies IEcommerceMallProductVariant.ICreate;
  const createdVariant =
    await api.functional.ecommerceMall.seller.products.variants.create(
      sellerConnection,
      {
        productId: seedProductId,
        body: initialVariantBody,
      },
    );
  typia.assert(createdVariant);
  // =====================================================================
  // STEP 1: First variant edit - change priceOverride (generates snapshot 1)
  // =====================================================================
  const firstEditBody = {
    price_override: typia.random<
      number & tags.Type<"uint32"> & tags.Minimum<1000>
    >(),
  } satisfies IEcommerceMallProductVariant.IUpdate;
  const editedVariant1 =
    await api.functional.ecommerceMall.seller.products.variants.update(
      sellerConnection,
      {
        productId: seedProductId,
        variantId: createdVariant.id,
        body: firstEditBody,
      },
    );
  typia.assert(editedVariant1);
  // =====================================================================
  // STEP 2: Second variant edit - change stockQuantity (generates snapshot 2)
  // =====================================================================
  const secondEditBody = {
    stock_quantity: 50,
  } satisfies IEcommerceMallProductVariant.IUpdate;
  const editedVariant2 =
    await api.functional.ecommerceMall.seller.products.variants.update(
      sellerConnection,
      {
        productId: seedProductId,
        variantId: createdVariant.id,
        body: secondEditBody,
      },
    );
  typia.assert(editedVariant2);
  // =====================================================================
  // VALIDATION 1: Admin retrieves variant snapshots
  // =====================================================================
  const snapshotRequest = {
    page: 1,
    limit: 10,
  } satisfies IEcommerceMallProductVariantSnapshot.IRequest;
  const snapshotResponse =
    await api.functional.ecommerceMall.products.variant_snapshots.index(
      adminConnection,
      {
        productId: seedProductId,
        body: snapshotRequest,
      },
    );
  typia.assert(snapshotResponse);
  // =====================================================================
  // VALIDATION 2: Verify pagination metadata
  // =====================================================================
  TestValidator.equals(
    "pagination total records",
    snapshotResponse.pagination.records,
    2,
  );
  TestValidator.equals(
    "pagination current page",
    snapshotResponse.pagination.current,
    1,
  );
  TestValidator.equals(
    "pagination limit",
    snapshotResponse.pagination.limit,
    10,
  );
  TestValidator.equals(
    "pagination total pages",
    snapshotResponse.pagination.pages,
    1,
  );
  // =====================================================================
  // VALIDATION 3: Verify snapshot count matches edits
  // =====================================================================
  TestValidator.equals(
    "snapshot count matches edits",
    snapshotResponse.data.length,
    2,
  );
  // =====================================================================
  // VALIDATION 4: Verify first snapshot contains priceOverride change
  // =====================================================================
  const firstSnapshot = snapshotResponse.data[0];
  typia.assert(firstSnapshot);
  TestValidator.equals(
    "first snapshot sku_code preserved",
    firstSnapshot.sku_code,
    initialVariantBody.sku_code,
  );
  TestValidator.equals(
    "first snapshot oldValues price_override is null",
    firstSnapshot.price_override,
    null,
  );
  TestValidator.equals(
    "first snapshot newValues price_override changed",
    editedVariant1.priceOverride,
    firstEditBody.price_override!,
  );
  // =====================================================================
  // VALIDATION 5: Verify second snapshot contains stockQuantity change
  // =====================================================================
  const secondSnapshot = snapshotResponse.data[1];
  typia.assert(secondSnapshot);
  TestValidator.equals(
    "second snapshot sku_code preserved",
    secondSnapshot.sku_code,
    initialVariantBody.sku_code,
  );
  TestValidator.equals(
    "second snapshot stockQuantity changed",
    secondSnapshot.stock_quantity,
    secondEditBody.stock_quantity,
  );
  // =====================================================================
  // VALIDATION 6: Verify timestamps are present and ordered
  // =====================================================================
  TestValidator.predicate(
    "first snapshot created_at is valid date-time",
    () => !isNaN(Date.parse(firstSnapshot.created_at)),
  );
  TestValidator.predicate(
    "second snapshot created_at is valid date-time",
    () => !isNaN(Date.parse(secondSnapshot.created_at)),
  );
  // First snapshot should be older than second
  TestValidator.predicate(
    "snapshots chronologically ordered",
    () => firstSnapshot.created_at < secondSnapshot.created_at,
  );
  // =====================================================================
  // VALIDATION 7: Verify date range filtering
  // =====================================================================
  const dateRangeRequest = {
    created_atGte: firstSnapshot.created_at,
    created_atLte: new Date().toISOString(),
  } satisfies IEcommerceMallProductVariantSnapshot.IRequest;
  const filteredSnapshots =
    await api.functional.ecommerceMall.products.variant_snapshots.index(
      adminConnection,
      {
        productId: seedProductId,
        body: dateRangeRequest,
      },
    );
  typia.assert(filteredSnapshots);
  TestValidator.equals(
    "date range filter returns 2 snapshots",
    filteredSnapshots.data.length,
    2,
  );
  // =====================================================================
  // VALIDATION 8: Verify admin can access snapshots (no 403)
  // =====================================================================
  // If we reach here, admin successfully accessed another seller's snapshots
  // This validates Section 409: Admins can view snapshots of any product
  TestValidator.predicate(
    "admin can access another seller's snapshots",
    snapshotResponse.data.length > 0,
  );
  // =====================================================================
  // VALIDATION 9: Verify snapshot immutability (admin view is read-only)
  // =====================================================================
  // Admin should only be able to retrieve, not modify snapshots
  // Verify snapshot data is immutable after creation
  TestValidator.equals(
    "snapshot data integrity preserved",
    snapshotResponse.data[0].id,
    firstSnapshot.id,
  );
  // =====================================================================
  // VALIDATION 10: Verify variant association in snapshots
  // =====================================================================
  TestValidator.predicate(
    "first snapshot has variant association",
    firstSnapshot.product_variant !== undefined &&
      firstSnapshot.product_variant.id !== undefined,
  );
  TestValidator.equals(
    "first snapshot variant ID matches",
    firstSnapshot.product_variant.id,
    createdVariant.id,
  );
  // =====================================================================
  // VALIDATION 11: Verify complete audit trail
  // =====================================================================
  TestValidator.equals(
    "admin sees all edits in audit trail",
    snapshotResponse.data.length,
    2,
  );
  TestValidator.equals(
    "first edit changed priceOverride",
    editedVariant1.priceOverride,
    firstEditBody.price_override!,
  );
  TestValidator.equals(
    "second edit changed stockQuantity",
    editedVariant2.stockQuantity,
    secondEditBody.stock_quantity,
  );
}

