  });
  typia.assert(seller);
  // Create seller-specific connection with token
  const authenticatedConnection: api.IConnection = {
    host: connection.host,
    headers: {
      Authorization: seller.token.access,
    },
  };
  // 2a. Test filter: stock_status = 'in_stock'
  const inStockResult =
