    if (seller === null) {
      throw new ForbiddenException("You're not enrolled");
    }

    return payload;
  } catch (error) {
    if (error instanceof UnauthorizedException) {
      throw error;
    }
    throw new UnauthorizedException("Authentication failed");
  }
}

