      [sortBy]: sortOrder,
    };
  const data = await MyGlobal.prisma.ecommerce_mall_product_variants.findMany({
    where: whereInput,
    orderBy: [orderByInput],
    skip,
    take: limit,
    select: {
      id: true,
      sku_code: true,
      stock_quantity: true,
      is_active: true,
      price_override: true,
      product: {
        select: {
          id: true,
          name: true,
          description: true,
          base_price: true,
          is_active: true,
          created_at: true,
          seller: {
            select: {
              id: true,
              email: true,
              approval_status: true,
              rejection_reason: true,
              is_suspended: true,
              is_banned: true,
              created_at: true,
            },
          },
          category: {
            select: {
              id: true,
              name: true,
              is_leaf: true,
              parent: {
                select: {
                  id: true,
                  name: true,
                  is_leaf: true,
                  created_at: true,
                  updated_at: true,
                  deleted_at: true,
                },
              },
              created_at: true,
              updated_at: true,
              deleted_at: true,
            },
          },
        },
      },
    },
  });
  const total = await MyGlobal.prisma.ecommerce_mall_product_variants.count({
    where: whereInput,
  });
  const transformedData = data.map((variant) => {
    const displayPrice: number =
      variant.price_override ?? variant.product.base_price;
    return {
      id: variant.id,
      skuCode: variant.sku_code,
      product: {
        id: variant.product.id,
        name: variant.product.name,
        description: variant.product.description ?? null,
        base_price: variant.product.base_price,
        is_active: variant.product.is_active,
        created_at: toISOStringSafe(variant.product.created_at),
        seller: {
          id: variant.product.seller.id,
          email: variant.product.seller.email,
          approval_status: typia.assert<"pending" | "approved" | "rejected">(
            variant.product.seller.approval_status,
          ),
          rejection_reason: variant.product.seller.rejection_reason ?? null,
          is_suspended: variant.product.seller.is_suspended,
          is_banned: variant.product.seller.is_banned,
          created_at: toISOStringSafe(variant.product.seller.created_at),
        },
        category: {
          id: variant.product.category.id,
          name: variant.product.category.name,
          is_leaf: variant.product.category.is_leaf,
          parent:
            variant.product.category.parent !== null
              ? {
                  id: variant.product.category.parent.id,
                  name: variant.product.category.parent.name,
                  is_leaf: variant.product.category.parent.is_leaf,
                  parent: null,
                  created_at: toISOStringSafe(
                    variant.product.category.parent.created_at,
                  ),
                  updated_at: toISOStringSafe(
                    variant.product.category.parent.updated_at,
                  ),
                  deleted_at:
                    variant.product.category.parent.deleted_at === null
                      ? null
                      : toISOStringSafe(
                          variant.product.category.parent.deleted_at,
                        ),
                }
              : null,
          created_at: toISOStringSafe(variant.product.category.created_at),
          updated_at: toISOStringSafe(variant.product.category.updated_at),
          deleted_at:
            variant.product.category.deleted_at === null
              ? null
              : toISOStringSafe(variant.product.category.deleted_at),
        },
      },
      stockQuantity: variant.stock_quantity,
      isActive: variant.is_active,
      priceOverride: variant.price_override,
      displayPrice: displayPrice,
    };
  });
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: transformedData,
  };
}

import { IEcommerceMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallCategory";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { EcommerceMallCategoryCollector } from "../collectors/EcommerceMallCategoryCollector";
import { AdminPayload } from "../decorators/payload/AdminPayload";
import { EcommerceMallCategoryTransformer } from "../transformers/EcommerceMallCategoryTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postEcommerceMallAdminCategories(props: {
  admin: AdminPayload;
  body: IEcommerceMallCategory.ICreate;
}): Promise<IEcommerceMallCategory> {
  if (props.body.name.length === 0 || props.body.name.length > 500) {
    throw new HttpException("Name must be between 1 and 500 characters", 400);
  }
  if (
    props.body.parent_category_id !== undefined &&
    props.body.parent_category_id !== null
  ) {
    const parentCategory =
      await MyGlobal.prisma.ecommerce_mall_categories.findFirst({
        where: {
          id: props.body.parent_category_id,
          deleted_at: null,
        },
      });
    if (!parentCategory) {
      throw new HttpException("Parent category not found", 400);
    }
    if (parentCategory.parent_category_id !== null) {
      throw new HttpException(
        "Subcategories can only be one level deep. Please select a parent category without subcategories.",
        400,
      );
    }
  }
  const existing = await MyGlobal.prisma.ecommerce_mall_categories.findFirst({
    where: {
      name: props.body.name,
      parent_category_id: props.body.parent_category_id ?? null,
      deleted_at: null,
    },
  });
  if (existing) {
    throw new HttpException(
      "A category with this name already exists under the same parent. Please choose a different name.",
      400,
    );
  }
  const created = await MyGlobal.prisma.ecommerce_mall_categories.create({
    data: await EcommerceMallCategoryCollector.collect({
      body: props.body,
    }),
    ...EcommerceMallCategoryTransformer.select(),
  });
  return await EcommerceMallCategoryTransformer.transform(created);
}

import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEcommerceMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallAdmin";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postEcommerceMallAuthAdminJoin(props: {
  body: IEcommerceMallAdmin.IJoin;
}): Promise<IEcommerceMallAdmin.IAuthorized> {
  const { email, password, href, referrer, ip } = props.body;
  const adminRequest =
    await MyGlobal.prisma.ecommerce_mall_admin_request_requests.findFirst({
      where: {
        deleted_at: null,
        request_status: "approved",
      },
      include: {
        customerRequests: true,
        sellerRequests: true,
      },
    });
  if (!adminRequest) {
    throw new HttpException("Admin request not found or not approved", 404);
  }
  const isCustomerRequest =
    adminRequest.customerRequests !== null &&
    adminRequest.customerRequests !== undefined;
  const sellerRequest = adminRequest.sellerRequests;
  const customerRequest = adminRequest.customerRequests;
  if (isCustomerRequest) {
    const customer = await MyGlobal.prisma.ecommerce_mall_customers.findUnique({
      where: { id: customerRequest!.customer_id },
    });
    if (!customer || customer.email !== email) {
      throw new HttpException("Admin request not found or not approved", 404);
    }
  } else if (sellerRequest) {
    const seller = await MyGlobal.prisma.ecommerce_mall_sellers.findUnique({
      where: { id: sellerRequest.seller_id },
    });
    if (!seller || seller.email !== email) {
      throw new HttpException("Admin request not found or not approved", 404);
    }
  }
  const existingAdmin = await MyGlobal.prisma.ecommerce_mall_admins.findFirst({
    where: { email: email },
  });
  if (existingAdmin) {
    throw new HttpException("Email already registered", 409);
  }
  const password_hash = await PasswordUtil.hash(password);
  const now = new Date();
  const admin = await MyGlobal.prisma.ecommerce_mall_admins.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      email: email,
      password_hash: password_hash,
      is_banned: false,
      ban_reason: null,
      created_at: now,
      updated_at: now,
    },
  });
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
  const session = await MyGlobal.prisma.ecommerce_mall_admin_sessions.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      admin_id: admin.id,
      ip: ip ?? "",
      href: href,
      referrer: referrer,
      created_at: now,
      expired_at: accessExpires,
    },
  });
  const token: IAuthorizationToken = {
    access: jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: session.id,
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "1h", issuer: "autobe" },
    ),
    refresh: jwt.sign(
      {
        type: "admin",
        id: admin.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: toISOStringSafe(now),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "7d", issuer: "autobe" },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };
  return {
    id: admin.id,
    email: admin.email,
    is_banned: admin.is_banned,
    ban_reason: admin.ban_reason,
    created_at: toISOStringSafe(admin.created_at),
    updated_at: toISOStringSafe(admin.updated_at),
    token,
  } satisfies IEcommerceMallAdmin.IAuthorized;
}

import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEcommerceMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallAdmin";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postEcommerceMallAuthAdminLogin(props: {
  ip: string;
  body: IEcommerceMallAdmin.ILogin;
}): Promise<IEcommerceMallAdmin.IAuthorized> {
  // 1. Find admin by email with password_hash
  const admin = await MyGlobal.prisma.ecommerce_mall_admins.findFirst({
    where: { email: props.body.email },
    select: {
      id: true,
      email: true,
      is_banned: true,
      ban_reason: true,
      created_at: true,
      updated_at: true,
      password_hash: true,
    } satisfies Prisma.ecommerce_mall_adminsSelect,
  });
  if (!admin) {
    throw new HttpException("Invalid credentials", 401);
  }
  // 2. Check if banned
  if (admin.is_banned) {
    throw new HttpException("Account is banned", 401);
  }
  // 3. Verify password
  const isValid = await PasswordUtil.verify(
    props.body.password,
    admin.password_hash,
  );
  if (!isValid) {
    throw new HttpException("Invalid credentials", 401);
  }
  // 4. Create new session with timestamps as string & tags.Format<'date-time'>
  const accessExpires: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(Date.now() + 60 * 60 * 1000),
  );
  const refreshExpires: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );
  const sessionId: string & tags.Format<"uuid"> = v4();
  const created_at: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(),
  );
  const session = await MyGlobal.prisma.ecommerce_mall_admin_sessions.create({
    data: {
      id: sessionId,
      admin: { connect: { id: admin.id } },
      created_at: created_at,
      expired_at: accessExpires,
      ip: props.ip,
      href: "",
      referrer: "",
    } satisfies Prisma.ecommerce_mall_admin_sessionsCreateInput,
  });
  // 5. Generate JWT tokens using only string timestamps
  const tokenPayload: {
    type: "admin";
    id: string & tags.Format<"uuid">;
    session_id: string & tags.Format<"uuid">;
    created_at: string & tags.Format<"date-time">;
  } = {
    type: "admin",
    id: admin.id,
    session_id: session.id,
    created_at: created_at,
  };
  const token: IAuthorizationToken = {
    access: jwt.sign(tokenPayload, MyGlobal.env.JWT_SECRET_KEY, {
      expiresIn: "1h",
      issuer: "autobe",
    }),
    refresh: jwt.sign(
      {
        ...tokenPayload,
        tokenType: "refresh",
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "7d", issuer: "autobe" },
    ),
    expired_at: accessExpires,
    refreshable_until: refreshExpires,
  };
  // 6. Return IAuthorized with admin data and token
  return {
    id: admin.id,
    email: admin.email,
    is_banned: admin.is_banned,
    ban_reason: admin.ban_reason,
    created_at: toISOStringSafe(admin.created_at) as string &
      tags.Format<"date-time">,
    updated_at: toISOStringSafe(admin.updated_at) as string &
      tags.Format<"date-time">,
    token,
  } satisfies IEcommerceMallAdmin.IAuthorized;
}

import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
