    }),
    MyGlobal.prisma.ecommerce_mall_cancellation_requests.count({
      where: whereInput,
    }),
  ]);
  return {
    pagination: {
      current: page,
      limit: take,
      records: total,
      pages: Math.max(Math.ceil(total / take), 0),
