  return {
    data: await ArrayUtil.asyncMap(
      data,
      EcommerceMallCartItemAtSummaryTransformer.transform,
    ),
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    } satisfies IPage.IPagination,
  };
